"""Startup: company types, special entities, post-registration."""

KYC = [('PAN card', 'Of every director, partner or member.'), ('Aadhaar card', 'For e-KYC and OTP verification.'),
       ('Passport-size photograph', 'Recent, plain background.'), ('Address proof', 'Bank statement, utility bill or mobile bill not older than 2 months.')]
OFFICE = [('Registered office proof', 'Electricity or gas bill of the premises, not older than 2 months.'),
          ('NOC from the owner', 'Or a rent agreement if the premises are rented.')]
MCA_STEPS = [('Share details', 'Send us the documents and tell us what needs to change. We confirm the checklist on WhatsApp.'),
             ('Drafting', 'We prepare resolutions, notices and the MCA form, and send them for your review.'),
             ('Signing and filing', 'Directors sign with their DSC and we file the form on the MCA portal.'),
             ('Approval', 'Once MCA approves, we share the challan, the approval and updated records.')]

